pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {DEP_BANK} from "../src/DEP_BANK.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    DEP_BANK c;

    function setUp() public {
        c = new DEP_BANK();
    }

    function _run(uint256 depAmount) internal {
        depAmount = bound(depAmount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(depAmount > 0);
        vm.assume(address(this).balance >= depAmount);
        try c.Deposit{value: depAmount}() {} catch { return; }
        uint256 balBefore;
        try c.balances(address(this)) returns (uint256 __r) { balBefore = __r; } catch { return; }
        uint contractBalBefore = address(c).balance;
        bool reverted = false;
        try c.Collect(0) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assertTrue(!reverted
            && c.balances(address(this)) == balBefore
            && address(c).balance == contractBalBefore);
    }

    function testFuzz_run(uint256 depAmount) public {
        _run(depAmount);
    }

    receive() external payable {}
}
